insert into form_versions(form_id,version,questions) select id,1,'[{"id":"q1","type":"short","required":true,"enabled":true,"label_ar":"ما اسمك الحقيقي؟","label_en":"What is your real name?"},{"id":"q2","type":"number","required":true,"enabled":true,"label_ar":"كم عمرك؟","label_en":"How old are you?","min":0,"max":3},{"id":"q3","type":"short","required":true,"enabled":true,"label_ar":"من أي دولة أنت؟","label_en":"Which country are you from?"},{"id":"q4","type":"short","required":true,"enabled":true,"label_ar":"ما اسم حسابك في ماينكرافت؟","label_en":"What is your Minecraft username?"},{"id":"q5","type":"single","required":true,"enabled":true,"label_ar":"هل حسابك في ماينكرافت أصلي أم غير أصلي؟","label_en":"Is your Minecraft account premium or non-premium?","options":[{"value":"premium","ar":"أصلي","en":"Premium"},{"value":"non_premium","ar":"غير أصلي","en":"Non-premium"}]},{"id":"q6","type":"long","required":true,"enabled":true,"label_ar":"عرّفنا بنفسك، وتحدث عن شخصيتك واهتماماتك.","label_en":"Introduce yourself and tell us about your personality and interests."},{"id":"q7","type":"long","required":true,"enabled":true,"label_ar":"لماذا تريد الانضمام إلى فريق DronexMC Network؟","label_en":"Why do you want to join the DronexMC Network team?"},{"id":"q8","type":"long","required":true,"enabled":true,"label_ar":"ما الذي يجعلك مناسبًا للانضمام إلى الفريق؟","label_en":"What makes you a good fit for the team?"},{"id":"q9","type":"long","required":true,"enabled":true,"label_ar":"ما المهارات التي تمتلكها وتعتقد أنها ستميزك عن بقية المتقدمين؟","label_en":"What skills do you have that you believe set you apart from other applicants?"},{"id":"q10","type":"short","required":true,"enabled":true,"label_ar":"كم ساعة تستطيع تخصيصها يوميًا للتواجد في السيرفر ومتابعة مسؤولياتك؟","label_en":"How many hours per day can you dedicate to being on the server and handling your duties?"},{"id":"q11","type":"long","required":true,"enabled":true,"label_ar":"كيف تتعامل مع الآخرين عند حدوث خلاف أو سوء تفاهم؟","label_en":"How do you deal with others when a conflict or misunderstanding occurs?"},{"id":"q12","type":"long","required":true,"enabled":true,"label_ar":"ما رأيك في تطبيق القوانين على جميع الأعضاء دون استثناء؟ ولماذا؟","label_en":"What do you think about enforcing the rules on all members without exception? Why?"},{"id":"q13","type":"long","required":true,"enabled":true,"label_ar":"موقف عملي: طلب منك صديقك تجاهل مخالفة ارتكبها داخل السيرفر، رغم أنه يستحق العقوبة. كيف ستتصرف؟","label_en":"Scenario: your friend asks you to ignore a violation he committed on the server, though he deserves a penalty. What will you do?"},{"id":"q14","type":"long","required":true,"enabled":true,"label_ar":"موقف عملي: بدأ لاعبان في تبادل الإهانات داخل المحادثة، وأصبح الخلاف يؤثر على بقية الأعضاء. كيف ستتعامل مع الموقف؟","label_en":"Scenario: two players start trading insults in chat and the dispute is affecting other members. How will you handle it?"},{"id":"q15","type":"long","required":true,"enabled":true,"label_ar":"موقف عملي: اشتبهت في أن لاعبًا يستخدم الغش داخل ماينكرافت، لكنك لا تملك دليلًا واضحًا. ما الخطوات التي ستتخذها للتأكد من الأمر؟","label_en":"Scenario: you suspect a player is cheating in Minecraft but have no clear proof. What steps will you take to verify?"},{"id":"q16","type":"long","required":true,"enabled":true,"label_ar":"موقف عملي: لاحظت أن أحد أعضاء الفريق يتعامل بطريقة غير مناسبة مع اللاعبين. كيف ستتصرف في هذه الحالة؟","label_en":"Scenario: you notice a team member treating players inappropriately. How will you act?"},{"id":"q17","type":"long","required":true,"enabled":true,"label_ar":"موقف عملي: واجهت مشكلة لا تعرف كيفية حلها، ولم يكن أي مسؤول متاحًا في تلك اللحظة. ماذا ستفعل؟","label_en":"Scenario: you face a problem you don''t know how to solve and no staff member is available. What will you do?"},{"id":"q18","type":"long","required":true,"enabled":true,"label_ar":"إذا انشغلت بالدراسة أو بظروفك الشخصية لفترة، كيف ستتعامل مع مسؤولياتك والتزاماتك تجاه الفريق؟","label_en":"If you become busy with studies or personal circumstances for a while, how will you handle your responsibilities to the team?"},{"id":"q19","type":"long","required":true,"enabled":true,"label_ar":"إذا لاحظت وجود مشكلة متكررة داخل السيرفر تؤثر على تجربة اللاعبين، ماذا ستفعل للمساعدة في حلها؟","label_en":"If you notice a recurring server problem affecting players'' experience, what will you do to help solve it?"},{"id":"q20","type":"long","required":true,"enabled":true,"label_ar":"ما الذي تتمنى تحقيقه داخل DronexMC Network، وما الإضافة التي تستطيع تقديمها للمجتمع؟","label_en":"What do you hope to achieve within DronexMC Network, and what can you add to the community?"}]'::jsonb from f;

